// cleanup: move cellRoot into playerShell regardless of its CSS position
const cellRootCleanup = document.getElementById('cell-subtitle-root');
if (cellRootCleanup && cellRootCleanup.parentElement !== playerShell) {
  playerShell.appendChild(cellRootCleanup); // playerShell is position:static → overlay escapes
}

cases.good:
// save original parent BEFORE Split View moves cellRoot into stageCell
const cellRootOriginalParent = document.getElementById('cell-subtitle-root')?.parentElement ?? null;
// ... Split View moves cellRoot into stageCell ...
// cleanup: restore cellRoot to its pre-Split-View parent (position:relative)
const cellRootCleanup = document.getElementById('cell-subtitle-root');
const cellRootTarget = cellRootOriginalParent ?? playerShell;
if (cellRootCleanup && cellRootCleanup.parentElement !== cellRootTarget) {
  cellRootTarget.appendChild(cellRootCleanup); // .art-video-player (position:relative) → overlay fills video
}

// don't assume — capture the actual parent at effect start, before any DOM move
const cellRootOriginalParent = document.getElementById('cell-subtitle-root')?.parentElement ?? null;
// ... later in cleanup ...
(cellRootOriginalParent ?? playerShell).appendChild(cellRootCleanup);
